/* short-answer-graphs: the module's own test. run_checks.sh runs it when the
 * course switches the module on (build.py --list-checks).
 *
 * On the course's own data: every figure has questions, every miss tag on them
 * names a reading question, every short-answer prompt has key points, and an
 * Exam 2 tracing's feedback uses tracing wording, not curve wording
 * (Intro-Pharmacology exam1-drill/src/browser_test.js check C8, line 325).
 * The build step: an image that is not in images.json, an image in two figures,
 * a miss tag in no table, a figure with no question, a prompt with no key points,
 * a prompt id used twice and a course with neither list each stop the build with
 * that reason (its test.js lines 60-84, the graph registry check).
 * On a scratch copy with Intro-Pharmacology's own rows added, verbatim (two
 * figures of graphs.js, the 10 questions on them from q_FIGS.js, q_L06.js and
 * q_PE2.js with their topics, their two images from images.json, five prompts
 * of sa4.js and sa3.js, and app.js's MISS and MISS2 tables, at 929cd62; question
 * and prompt ids prefixed sag-, the professor and the skill set to the course's own, the
 * `fg` field left out because the core reads `fg` as a drawn structure), in
 * Chromium (its browser_test.js lines 114-123 ported, and more): one card per
 * figure, in a fold per exam with the active exam open; Drill this figure opens
 * a question with its figure; a wrong pick names the reading question skipped
 * and opens the figure's reading; the end of the pass counts the right answers
 * and lists what was skipped; the card then shows the wrong answer, the tag
 * skipped and Redo wrong, which asks only that question; a tracing uses the
 * tracing wording; the counts survive a reload. The Short answer page: one
 * prompt at a time with its lecture and form, the draft kept as typed, the model
 * answer and key points shown on Check, the ticks counted and kept through a
 * reload, Next, Previous, Shuffle and Clear. On a copy with short answers only:
 * no Graphs tab.
 *
 *     node features/short-answer-graphs/test.js
 */
const fs = require('fs'), path = require('path');
const L = require(path.join(__dirname, '..', '..', 'check_lib'));
const NAME = 'features/short-answer-graphs/test.js';
const {check} = L;
delete process.env.DRILL_PAGE;

/* Intro-Pharmacology's rows at 929cd62 (graphs.js, q_FIGS.js, q_L06.js, q_PE2.js,
   their TOPICS entries, images.json, sa4.js, sa3.js, app.js MISS and MISS2). */
const IP = {"graphs":[{"key":"rev-pindolol","alts":[],"title":"Review page 11: one drug in two systems, from 100% down to about 50% and from 0 up to about 50%","group":"Other","source":"Pharmacodynamics reviews.pdf page 11","read":["Two dashed curves of one drug: the upper starts at 100% (the system is fully active) and falls to about 50%; the lower starts at 0 and rises to about 50%.","Does it have efficacy? Yes, it brings the low system up: neutral antagonists (metoprolol) are out.","Did it go to 0? No: the inverse agonist (loratadine) is out.","Did it reach 100%? No, it wants the system at about 50%: a partial agonist, pindolol, which brings a low heart rate up and a high heart rate down.","The trap: a curve that goes down is not automatically an inverse agonist; look at where it stops."],"method":"Ask: does it have efficacy, did it go to 0, did it go to 100%; the answers yes, no, no are a partial agonist.","asks":["This drug is: Full agonist / Partial agonist / Inverse agonist / Competitive antagonist / Irreversible antagonist","This drug is most likely: (drug-list names)","Which feature rules out an inverse agonist / a neutral antagonist?","Why might pindolol be chosen for a hypertensive patient with a low heart rate?"]},{"key":"pe2-gi-tracing","alts":[],"exam":2,"title":"GI smooth muscle tone: pilocarpine before and after drug X (PollEV, Exam 2)","group":"Other","source":"PollEV’s Exam 2.pdf (poll screenshot)","read":["This is a tracing, not a dose–response curve: the y-axis is GI smooth muscle tone over time; the dotted lines mark the two pilocarpine doses and the arrow marks drug X.","First pilocarpine: tone rises and comes back down. Pilocarpine is a muscarinic agonist; on GI M3 (Gq, ↑Ca++) it increases motility and tone.","Drug X: tone falls a little below the starting line; the resting parasympathetic (PNS) tone of the gut has been blocked.","Second pilocarpine: no rise at all. The receptor pilocarpine acts on is blocked, so X is a muscarinic (M3) antagonist: atropine.","The trap: a drug that stops acetylcholine release (Botox) or blocks Nm (rocuronium) would not stop a direct muscarinic agonist on smooth muscle; a cholinesterase inhibitor or another agonist would raise tone."],"method":"Name the agonist and its receptor, read what it does before X, then ask whether X helped (bigger response) or made life more difficult (smaller or none), and pick the drug that blocks that receptor.","asks":["Drug X is most likely to be: Carbachol / Neostigmine / Rocuronium / Atropine / Varenicline","What does pilocarpine do to GI tone, and through which receptor?","Why does the second pilocarpine dose produce no rise?","Which other drug could be drug X?"]}],"qs":[{"id":"FG-049","fg":"partial","lecture":"FG","prof":"Gottlieb","tier":"new","topic":"FG","sub":"read","skill":"figure","concept":"pindolol-partial-agonist-two-baselines","tags":["poll","figure-drill","pindolol"],"source":"both","img":"rev-pindolol","imgAlt":"Response percent of control against agonist concentration with two dashed curves: an upper curve starts at 100% and falls to about 50%; a lower curve starts at 0 and rises to about 50%; both meet at about 50% at high concentration","imgCap":"One drug in two systems: starting at 100% (R < R*) and starting at 0","stem":"One drug is given to two systems: from 100% it brings the response down to about 50%, and from 0 it brings the response up to about 50%. Which statement is CORRECT about this drug?","options":[{"t":"It has efficacy","correct":false,"miss":"read","why":"Correct (it brings the low system up), but not the only correct statement."},{"t":"It is not an inverse agonist","correct":false,"miss":"read","why":"Correct (it does not take the high system to 0), but not the only correct statement."},{"t":"It is a partial agonist","correct":false,"miss":"read","why":"Correct (it wants the system at about 50%, not 100%), but not the only correct statement."},{"t":"All of the above","correct":true,"why":"Efficacy yes, 0 no, 100% no: a partial agonist, and all three statements hold."}],"teach":"Does the drug have efficacy? Yes, it brings things up, so the neutral antagonists are out. Did it go to 0? No, so the inverse agonist is out. Did it change the efficacy to 100%? No, it wants about 50%. That is a partial agonist, and every statement is correct.","quote":"does this drug has efficacy? Yes, it’s bringing things up ... Did it go to 0? No, so we get rid of an inverse agonist ... Did it change the efficacy to 100%. Definitely not. They want you about 50%, so that is a partial agonist","cite":"Pharmacodynamics reviews.pdf page 11; transcript 9/30"},{"id":"FG-050","fg":"partial","lecture":"FG","prof":"Gottlieb","tier":"new","topic":"FG","sub":"which","skill":"drug","concept":"pindolol-partial-agonist-two-baselines","tags":["poll","figure-drill","pindolol","drug-list"],"source":"both","img":"rev-pindolol","imgAlt":"Response percent of control against agonist concentration with two dashed curves: an upper curve starts at 100% and falls to about 50%; a lower curve starts at 0 and rises to about 50%; both meet at about 50% at high concentration","imgCap":"One drug in two systems: starting at 100% (R < R*) and starting at 0","stem":"One drug at the β1 receptor is given to two systems: from 100% it brings the response down to about 50%, and from 0 it brings the response up to about 50%. This drug is most likely:","options":[{"t":"Metoprolol","correct":false,"miss":"baseline","why":"Metoprolol is a neutral antagonist: no efficacy, so it would leave both baselines where they are."},{"t":"Pindolol","correct":true,"why":"A partial β-blocker: it has partial efficacy, so it brings a fully active system down and an inactive system up, toward about 50%."},{"t":"Loratadine","correct":false,"miss":"baseline","why":"Loratadine is the inverse agonist and acts at H1; an inverse agonist would take the upper system down to 0."},{"t":"Phenoxybenzamine","correct":false,"miss":"baseline","why":"Phenoxybenzamine is an irreversible α antagonist; antagonists do not change the baseline."},{"t":"Epinephrine","correct":false,"miss":"emax","why":"Epinephrine is a full agonist; it would take the lower system all the way to 100%, not stop at 50%."}],"teach":"A drug that moves both systems toward the same middle level has efficacy of its own, less than a full agonist and more than none: a partial agonist. At the β1 receptor that is pindolol, the partial β-blocker: if the heart rate is too low it brings it up, if it is too high it brings it down.","quote":"Pindolol, which is a partial beta blocker, if your heart is too low, it’s gonna bring things up. If it’s too high, it’s gonna bring things down.","cite":"Pharmacodynamics reviews.pdf page 11; transcript 9/30"},{"id":"FG-051","fg":"inverse","lecture":"FG","prof":"Gottlieb","tier":"new","topic":"FG","sub":"why","skill":"figure","concept":"pindolol-partial-agonist-two-baselines","tags":["poll","figure-drill"],"source":"both","img":"rev-pindolol","imgAlt":"Response percent of control against agonist concentration with two dashed curves: an upper curve starts at 100% and falls to about 50%; a lower curve starts at 0 and rises to about 50%; both meet at about 50% at high concentration","imgCap":"One drug in two systems: starting at 100% (R < R*) and starting at 0","stem":"Which feature of the figure rules out an inverse agonist?","options":[{"t":"The upper curve goes down from 100% as the concentration rises","correct":false,"miss":"baseline","why":"An inverse agonist also brings a fully active system down; going down alone does not rule it out."},{"t":"The upper curve stops at about 50% instead of going to 0","correct":true,"why":"An inverse agonist brings everything down to 0 or keeps it at 0; this drug stops half way, so it has efficacy of its own."},{"t":"Both curves are dashed","correct":false,"miss":"read","why":"Dashed only marks the drug being studied; it says nothing about its class."},{"t":"The two curves are the same drug","correct":false,"miss":"read","why":"The same drug in two systems is the set-up of the figure, not what separates the classes."}],"teach":"Did it go to 0? No. An inverse agonist wants all the receptors inactive, so from 100% it would take the response to 0. This drug stops at about 50% from above and comes up to about 50% from below: it has its own level of efficacy, a partial agonist.","quote":"Did it go to 0? No, so we get rid of an inverse agonist, because an inverse ago will bring everything down to 0 or keep at 0 if it’s 0.","cite":"Pharmacodynamics reviews.pdf page 11; transcript 9/30"},{"id":"FG-052","fg":"partial","lecture":"FG","prof":"Gottlieb","tier":"new","topic":"FG","sub":"why","skill":"figure","concept":"pindolol-partial-agonist-two-baselines","tags":["poll","figure-drill","metoprolol"],"source":"both","img":"rev-pindolol","imgAlt":"Response percent of control against agonist concentration with two dashed curves: an upper curve starts at 100% and falls to about 50%; a lower curve starts at 0 and rises to about 50%; both meet at about 50% at high concentration","imgCap":"One drug in two systems: starting at 100% (R < R*) and starting at 0","stem":"Which feature of the figure rules out a neutral antagonist such as metoprolol?","options":[{"t":"The drug moves the response in both systems","correct":true,"why":"A neutral antagonist has affinity but no efficacy: it does not change the balance of active and inactive receptors, so both baselines would stay flat."},{"t":"The upper curve goes down from 100% toward 50%","correct":false,"miss":"baseline","why":"Going down alone could be read as blocking; what matters is that the lower curve also goes up, which needs efficacy."},{"t":"The curves meet at about 50%","correct":false,"miss":"baseline","why":"The meeting point tells you the level of the partial agonist, not why an antagonist is excluded."},{"t":"The upper system starts at 100%","correct":false,"miss":"read","why":"The starting point describes the system (fully active), not the drug."}],"teach":"Does this drug have efficacy? Yes, it brings the low system up and the high system down. A neutral antagonist is neutral: it does not change the baseline in either system. So metoprolol, with no efficacy, is out; pindolol, a partial agonist, fits.","quote":"So we got rid of those guys that are neutral because they will not change the baseline.","cite":"Pharmacodynamics reviews.pdf page 11; transcript 9/30"},{"id":"L06-025","fg":"partial","lecture":"L06","prof":"Gottlieb","tier":"new","topic":"L06","sub":"method","skill":"figure","concept":"pindolol-partial-agonist-two-baselines","tags":["poll","pindolol"],"source":"both","img":"rev-pindolol","imgAlt":"Response percent of control against agonist concentration with two dashed curves: an upper curve starts at 100% and falls to about 50%; a lower curve starts at 0 and rises to about 50%; both meet at about 50% at high concentration","imgCap":"One drug in two systems: starting at 100% (R < R*) and starting at 0","stem":"One drug is given to two systems. When the system starts at 100% activity the drug brings the response down to about 50%; when the system starts at 0 it brings the response up to about 50%. This drug is:","options":[{"t":"Full agonist","correct":false,"miss":"emax","why":"A full agonist would take the lower system all the way to 100%; this drug stops at about 50%."},{"t":"Partial agonist","correct":true,"why":"It has efficacy (it brings the low system up), it does not go to 0 (not inverse), and it does not reach 100%: it wants the system at about 50%, from either direction."},{"t":"Inverse agonist","correct":false,"miss":"baseline","why":"An inverse agonist would take the upper system down to 0, not stop at 50%."},{"t":"Competitive antagonist","correct":false,"miss":"baseline","why":"A neutral antagonist does not change the baseline in either system; this drug moves both."},{"t":"Irreversible antagonist","correct":false,"miss":"baseline","why":"An antagonist has no efficacy; this drug raises the response in the low system."}],"teach":"Does the drug have efficacy? Yes, it brings the low system up, so the neutral antagonists are out. Did it bring the response to 0? No, so the inverse agonist is out. Did it change the efficacy to 100%? No, it wants about 50%. That is a partial agonist: pindolol, a partial β-blocker, brings a low heart rate up and a high heart rate down.","quote":"does this drug has efficacy? Yes, it’s bringing things up ... Did it go to 0? No, so we get rid of an inverse agonist ... Did it change the efficacy to 100%. Definitely not. They want you about 50%, so that is a partial agonist","cite":"Pharmacodynamics reviews.pdf page 11; transcript 9/30"},{"id":"PE2-030","lecture":"PE2","prof":"Gottlieb","tier":"new","level":2,"ladder":"atropine-poisoning","ladderName":"Atropine poisoning and physostigmine","topic":"PE2","sub":"verbatim","skill":"figure","concept":"gi-tracing-drug-x-atropine","tags":["poll","pollev","verbatim","figure-drill","on-exam-verbatim","exam-cue"],"source":"both","img":"pe2-gi-tracing","imgAlt":"Tracing of GI smooth muscle tone over time: flat baseline, a rise and fall after the first pilocarpine dose, an arrow marked X where tone dips slightly, then no rise after the second pilocarpine dose","imgCap":"GI smooth muscle tone: pilocarpine, drug X at the arrow, then pilocarpine again","stem":"The figure below shows tracing of GI smooth muscle in response to pilocarpine before and after drug X. Drug X is most likely to be:","options":[{"t":"Carbachol","correct":false,"miss":"direction","why":"A muscarinic agonist would help pilocarpine and raise tone; after X, pilocarpine has no effect at all."},{"t":"Neostigmine","correct":false,"miss":"direction","why":"A cholinesterase inhibitor makes acetylcholine more potent and would raise GI tone, not abolish the pilocarpine response."},{"t":"Rocuronium","correct":false,"miss":"class","why":"Rocuronium blocks Nm at skeletal muscle; GI smooth muscle tone is controlled by muscarinic M3 receptors."},{"t":"Atropine","correct":true,"why":"After X, pilocarpine no longer raises tone: X blocks the muscarinic (M3) receptor that pilocarpine activates. Atropine is a non-selective, reversible muscarinic antagonist."},{"t":"Varenicline","correct":false,"miss":"class","why":"A partial agonist at α4/β2 Nn receptors in the brain; it does not act on GI smooth muscle muscarinic receptors."}],"teach":"Read the tracing in order. Pilocarpine alone raises GI smooth muscle tone (a muscarinic agonist on M3, Gq, ↑Ca++, contraction). Drug X is given at the arrow, tone drifts slightly below the starting line, and the second dose of pilocarpine produces no rise; a drug that removes the response to a muscarinic agonist is a muscarinic antagonist, atropine.","quote":"If it's in the M3, depending where it is, let's say it's on the GI tract, I'm gonna increase motility and tone.","note":"On the sheet this poll is a PollEV screenshot with no green highlight. The screenshot shows Atropine as the recorded response, with the student’s handwritten “Ant M3” (M3 antagonist) beside it and “muscarinic agonist (M1, M2, M3)” under the first “Pilocarpine”. Not in the 10/5 audio; run on 10/6, where he walked through it (up = constriction, down = relaxation; pilocarpine on M3; X makes pilocarpine's job harder; carbachol, neostigmine, rocuronium and varenicline eliminated): “So the best answer would be what atropine. So atropine is blocking the ability of pilocarpine to bind and activate those receptors and produce that constriction.” Before the walk-through he read the class result as “C as in cat” and said it was correct, but on the sheet Atropine is option D; the key is atropine. Exam cue the same day: “you're gonna get 1 to 2 of these little graphs on your uh test, and this is how you're gonna apply the knowledge, right?” He said on 10/6 that one of the 10/5 polls and one of the 10/6 polls will be on Exam 2 word for word (“one of the questions today and one of the questions yesterday I'm gonna use verbatim, word by word on your exam”), without naming which; every poll run on those two days is tagged on-exam-verbatim.","cite":"PollEV’s Exam 2.pdf poll 18; transcript 10/5; transcript 10/6; PCOL-Cholinergic-26s.pdf slides 12–14, 17, 19"},{"id":"PE2-031","lecture":"PE2","prof":"Gottlieb","tier":"new","level":1,"topic":"PE2","sub":"variant","skill":"figure","concept":"gi-tracing-pilocarpine-m3","tags":["poll","pollev","figure-drill"],"source":"both","img":"pe2-gi-tracing","imgAlt":"Tracing of GI smooth muscle tone over time: flat baseline, a rise and fall after the first pilocarpine dose, an arrow marked X where tone dips slightly, then no rise after the second pilocarpine dose","imgCap":"GI smooth muscle tone: pilocarpine, drug X at the arrow, then pilocarpine again","stem":"In the tracing below, what does the first dose of pilocarpine do to GI smooth muscle tone, and through which receptor?","options":[{"t":"Raises tone through M3 (Gq)","correct":true,"why":"The tracing rises after pilocarpine: a muscarinic agonist on M3 (Gq, PLC, IP3, ↑Ca++) contracts GI smooth muscle, increasing motility and tone."},{"t":"Lowers tone through M2 (Gi)","correct":false,"miss":"read","why":"The tracing goes up, not down, and GI smooth muscle tone is an M3 effect."},{"t":"Raises tone through Nm (ion channel)","correct":false,"miss":"class","why":"Pilocarpine has no effect on nicotinic receptors; Nm is at skeletal muscle."},{"t":"Lowers tone through α2 (Gi)","correct":false,"miss":"read","why":"α2 activation is what decreases GI activity, but pilocarpine is a muscarinic agonist and the tracing goes up."},{"t":"No change in tone","correct":false,"miss":"read","why":"The tracing clearly rises and falls back after the first pilocarpine dose."}],"teach":"Pilocarpine is a non-selective, reversible muscarinic agonist with no effect on nicotinic receptors. In the gastrointestinal (GI) tract, M3 (Gq) raises Ca++ and increases motility and tone, which is the first peak on the tracing. Sympathetic α2 does the opposite (decreased GI activity).","quote":"If it's in the M3, depending where it is, let's say it's on the GI tract, I'm gonna increase motility and tone.","cite":"PollEV’s Exam 2.pdf poll 18 (variant); transcript 10/5; PCOL-Cholinergic-26s.pdf slides 12–14; Autonomic Nervous System.pdf slide 31"},{"id":"PE2-032","lecture":"PE2","prof":"Gottlieb","tier":"new","level":2,"ladder":"atropine-poisoning","ladderName":"Atropine poisoning and physostigmine","topic":"PE2","sub":"variant","skill":"figure","concept":"gi-tracing-m3-blocked","tags":["poll","pollev","figure-drill"],"source":"both","img":"pe2-gi-tracing","imgAlt":"Tracing of GI smooth muscle tone over time: flat baseline, a rise and fall after the first pilocarpine dose, an arrow marked X where tone dips slightly, then no rise after the second pilocarpine dose","imgCap":"GI smooth muscle tone: pilocarpine, drug X at the arrow, then pilocarpine again","stem":"In the tracing below, why does the second dose of pilocarpine produce no rise in tone?","options":[{"t":"Drug X blocks the M3 receptors","correct":true,"why":"Pilocarpine acts directly on muscarinic M3 receptors; once X occupies them, pilocarpine cannot activate them, so tone does not rise."},{"t":"Drug X blocks the Nm receptors","correct":false,"miss":"class","why":"Nm is at skeletal muscle; pilocarpine acts on muscarinic receptors of smooth muscle."},{"t":"Drug X inhibits cholinesterase","correct":false,"miss":"direction","why":"A cholinesterase inhibitor makes acetylcholine more potent, which would raise tone."},{"t":"Drug X stops acetylcholine release","correct":false,"miss":"class","why":"Stopping acetylcholine release (Botox) does not stop pilocarpine, a direct agonist that binds the muscarinic receptor itself."},{"t":"Drug X is a second muscarinic agonist","correct":false,"miss":"direction","why":"A second agonist on M3 would add to pilocarpine and raise tone; the tracing shows the response abolished."}],"teach":"Pilocarpine is a direct-acting muscarinic agonist: it binds the M3 receptor itself and does not need acetylcholine. The only way to remove its effect is to block that receptor with a muscarinic antagonist such as atropine. A drug acting before the receptor (less acetylcholine release) leaves the pilocarpine response in place, and a cholinesterase inhibitor or a second agonist would raise tone.","quote":"What I need you to know is that it does not bind or activate the nicotinic receptors. It only has affinity for the muscarinics. That's going to be a very key information for you","cite":"PollEV’s Exam 2.pdf poll 18 (variant); transcript 10/5; PCOL-Cholinergic-26s.pdf slides 14, 19; PCOL-NMJ_PCOL_2026s_pptx.pdf slides 46–50"},{"id":"PE2-033","lecture":"PE2","prof":"Gottlieb","tier":"new","level":1,"topic":"PE2","sub":"variant","skill":"figure","concept":"gi-tracing-pns-tone","tags":["poll","pollev","figure-drill"],"source":"both","img":"pe2-gi-tracing","imgAlt":"Tracing of GI smooth muscle tone over time: flat baseline, a rise and fall after the first pilocarpine dose, an arrow marked X where tone dips slightly, then no rise after the second pilocarpine dose","imgCap":"GI smooth muscle tone: pilocarpine, drug X at the arrow, then pilocarpine again","stem":"In the tracing below, tone falls slightly below the starting line when drug X is given, before the second pilocarpine dose. Which explains the fall?","options":[{"t":"X blocks the resting PNS tone","correct":true,"why":"The GI tract has a predominant parasympathetic (PNS) tone through M3; blocking it lowers tone below the starting line (anti-DUMBBELSS constipation)."},{"t":"X activates GI M3 receptors","correct":false,"miss":"direction","why":"Activating M3 would raise tone, and pilocarpine would still work."},{"t":"X blocks Nm receptors in the gut","correct":false,"miss":"class","why":"Nm receptors are at skeletal muscle; GI smooth muscle tone is muscarinic."},{"t":"X inhibits cholinesterase","correct":false,"miss":"direction","why":"More acetylcholine would raise tone, not lower it."}],"teach":"At rest the gastrointestinal (GI) tract runs on a predominant parasympathetic (PNS) tone through M3. A muscarinic antagonist blocks that tone as well as any added agonist: tone falls a little when X is given, and pilocarpine then cannot raise it. This is the anti-DUMBBELSS constipation of atropine.","quote":"And if you know what the agonist is going to do, what do you think the antagonist is going to do? The opposite, the anti-dumbbells, constipation, can't pee, can't cry, can't sweat, can't see, right?","cite":"PollEV’s Exam 2.pdf poll 18 (variant); transcript 10/5; PCOL-Cholinergic-26s.pdf slides 13, 19"},{"id":"PE2-034","lecture":"PE2","prof":"Gottlieb","tier":"new","level":2,"topic":"PE2","sub":"variant","skill":"figure","concept":"gi-tracing-other-antagonist","tags":["poll","pollev","figure-drill"],"source":"both","img":"pe2-gi-tracing","imgAlt":"Tracing of GI smooth muscle tone over time: flat baseline, a rise and fall after the first pilocarpine dose, an arrow marked X where tone dips slightly, then no rise after the second pilocarpine dose","imgCap":"GI smooth muscle tone: pilocarpine, drug X at the arrow, then pilocarpine again","stem":"Which of the following could also be drug X in the tracing below?","options":[{"t":"Scopolamine","correct":true,"why":"Like atropine, scopolamine is a natural, non-selective, reversible muscarinic antagonist; it blocks GI M3 and gives constipation."},{"t":"Bethanechol","correct":false,"miss":"direction","why":"A “chol” muscarinic agonist; it would raise GI tone like pilocarpine."},{"t":"Neostigmine","correct":false,"miss":"direction","why":"A cholinesterase inhibitor raises acetylcholine and increases GI tone."},{"t":"Succinylcholine","correct":false,"miss":"class","why":"An Nm agonist at skeletal muscle; it does not act on GI smooth muscle M3."},{"t":"Botox","correct":false,"miss":"class","why":"Stopping acetylcholine release does not stop pilocarpine, which binds the M3 receptor directly."}],"teach":"Drug X behaves like a muscarinic antagonist. Atropine and scopolamine are the natural, non-selective, reversible muscarinic antagonists, and any “trop” drug is atropine-like as well. Agonists (the “chol” drugs, pilocarpine) and cholinesterase inhibitors (the -stigmines) would raise tone instead.","quote":"So scopolamine is a non-selective muscarinic antagonist, uh, most times we use for motion sickness.","cite":"PollEV’s Exam 2.pdf poll 18 (variant); transcript 10/5; PCOL-Cholinergic-26s.pdf slides 11, 17, 24"}],"topics":[{"id":"FG","name":"Figure drills: his PollEV, Jeopardy and review figures","prof":"Gottlieb","lecture":"FG","cite":"PollEV_s.pdf; Pharmacodynamics reviews.pdf; Jeopardy 9/30; Part 3","subs":[{"id":"read","name":"Read the figure","cite":"PollEV_s.pdf pages 2–5; Jeopardy 9/30"},{"id":"which","name":"Which curve, which drug","cite":"PollEV_s.pdf pages 3 and 5; Pharmacodynamics reviews.pdf pages 5–11"},{"id":"why","name":"Which feature rules a class in or out","cite":"Pharmacodynamics reviews.pdf pages 5–11"},{"id":"predict","name":"Predict the curve for a different drug","cite":"PollEV_s.pdf; Pharmacodynamics reviews.pdf"}]},{"id":"L06","name":"Day 6: reading a curve question","prof":"Gottlieb","lecture":"L06","cite":"Day 6 (9/30) — Pharmacodynamics reviews.pdf, Part 3","subs":[{"id":"p3","name":"Desired vs undesired effects","cite":"Part 3 pages 1–2"},{"id":"recap","name":"Recap figure A–E","cite":"reviews page 3"},{"id":"base50","name":"The 50% baseline figure","cite":"reviews page 4"},{"id":"method","name":"The three questions for any curve","cite":"reviews pages 5–11"},{"id":"signal","name":"Signal transduction in his words","cite":"transcript 9/30"}]},{"id":"PE2","name":"His Exam 2 polls (verbatim)","prof":"Gottlieb","lecture":"PE2","cite":"PollEV’s Exam 2.pdf; Jeopardy 10/8 and review 10/9 (PollEV screenshots)","subs":[{"id":"verbatim","name":"His polls, word for word","cite":"PollEV’s Exam 2.pdf"},{"id":"variant","name":"Same idea, different correct option","cite":"PollEV’s Exam 2.pdf"}]}],"images":{"rev-pindolol":"data:image/png;base64,","pe2-gi-tracing":"data:image/png;base64,"},"sa":[{"id":"SA4-01","lecture":"L21","form":"her","q":"A patient of self-identified non-African ancestry is starting warfarin. Genotyping shows CYP2C9*3/*3 and VKORC1 variant at -1639 (the -1639G>A haplotype). Compared with the average starting dose, does this patient need relatively more or relatively less warfarin, and why? Please answer in no more than 2 sentences.","model":"The patient needs relatively less warfarin than the average starting dose. CYP2C9 is the enzyme that metabolizes the potent S-warfarin and the *3 allele has low activity, so the drug is cleared slowly, and VKORC1 is warfarin's target whose -1639 variant lowers the enzyme's expression and activity, so with a less active target and slower metabolism less drug is needed.","points":["Relatively less warfarin than the average starting dose","CYP2C9 metabolizes S-warfarin; the *3 variant lowers that activity, so the drug is cleared slowly (PK)","VKORC1 is warfarin's target; the -1639 variant lowers its activity, so a less active target needs less drug (PD)","Both variants push the dose the same way: down"],"quote":"they're, they're variant, homozygous variant for VQRC1, and homozygous variant for 2C9. The target has low activity and the metabolizing enzymes have low activity. ... they need the lowest drug, lowest amount of drug","cite":"CPIC warfarin guideline, 2017 update (Canvas: pharmacogenomics resources), Figure 1 (p. 398) and Figure 2 (p. 401); PGx-Examples-Students-Fall-2026.pdf slide 'Integrated Both PK and PD' (p. 57); transcript 10/26 and 10/27","note":"Her exam case format, posed on 10/27: given genotypes and ancestry, is the dose relatively more or less, and why. The quoted wording is from the 10/26 two-gene case where both variants lower the dose; on 10/27 she walked the non-African branch of Figure 2. A CYP4F2*3 variant would push the dose up instead (opposite effect); the *2/*3 and *3/*3 poor-metabolism genotype carries a Figure 2 footnote to consider an alternative agent."},{"id":"SA4-02","lecture":"L21","form":"her","q":"A patient is about to start abacavir for HIV. According to its drug label, which gene and allele is tested, and is it the patient or a tumor that is genotyped, and what should be done if the result is positive? Please answer in no more than 2 sentences.","model":"The patient (not a tumor) is screened for the HLA-B gene, specifically the HLA-B*5701 allele, before the drug is started. A positive result means abacavir is contraindicated and should not be given, because carriers are at high risk of a serious hypersensitivity reaction with multi-organ involvement.","points":["Gene HLA-B, allele HLA-B*5701","The patient is genotyped, not a tumor","A positive result means abacavir is contraindicated (do not give it)","The screen prevents a serious multi-organ hypersensitivity reaction"],"quote":"So for back of here, it's HLAB 5701. What happens if a patient has this genotype present? Hypersensitivity reaction, where? Multi-organ failure.","cite":"FDA label for abacavir (Ziagen), 2020 revision (Canvas), Boxed Warning (p. 2), Contraindications (p. 3) and Warnings and Precautions 5.1 (p. 4); PGx-Resources-and-Cases-Students-Fall-2026.pdf drug-label worksheet; transcript 10/27","note":"'Back of here/ear' is the caption's rendering of abacavir. She contrasted abacavir (HLA-B*5701, multi-organ reaction) with carbamazepine (HLA-B*1502, skin reaction): same HLA-B gene, different variant. The label names no specific test method for abacavir, only to screen for the allele before starting; the contraindication on a positive result is from the label Contraindications section, covered in the worksheet report-back ('are you genotyping the patient? Yes')."},{"id":"SA3-02","lecture":"L14","form":"objective","q":"Define the therapeutic index (TI), the margin of safety (MOS) and the margin of exposure (MOE). Which one gives an idea of the slope of the dose-response curve, and why?","model":"TI is the toxic dose over the therapeutic dose, with the same percentage of animals in numerator and denominator (usually 50%); MOS is the toxic dose in 1% of animals over the effective dose in 99%, and because it uses different percentages it gives an idea of the slope, which TI does not. MOE is the NOAEL (no observable adverse effect level, the highest dose tested in animals with no adverse effect) over the chronic human exposure, used for repeated exposures to non-therapeutic compounds such as pollutants or occupational exposures.","points":["TI = toxic dose / therapeutic dose, with the same percentage of animals in both (usually 50%)","MOS = toxic dose in 1% / effective dose in 99%; the different percentages show the slope, TI does not","MOE = NOAEL / chronic exposure, for repeated exposures to non-therapeutic compounds","The values are used to compare one compound with another (for example, which contaminant is more dangerous)"],"quote":"what's the toxic dose for 1% of the animals over the effective dose of 99% of the animals. That's the margin of safety. And because we use a different percentage, it gives you an idea of the slope of your dose response curve, whereas the therapeutic index does not.","cite":"Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘Values Developed from Dose-Response’; transcript 10/13; NOAEL definition from Casarett and Doull ch. 2 (assigned reading)","note":"On 10/13 she also phrased the NOAEL as the lowest dose given without a bad response; Casarett and Doull define it as the highest dose tested without significant toxicity, and that definition is used here."},{"id":"SA3-06","lecture":"L14","form":"objective","q":"Define on-target and off-target adverse drug effects, and classify the drowsiness caused by diphenhydramine.","model":"An on-target adverse effect occurs when the drug acts on the receptor it was designed for, either in the intended tissue at too high a dose or in the wrong tissue; an off-target effect occurs when the drug acts on receptors it was not intended to find, in either tissue. Diphenhydramine's drowsiness is on-target in the wrong tissue: it acts on histamine receptors in the brain.","points":["On-target: the intended receptor, in the intended tissue (dose too high) or in the wrong tissue","Off-target: an unintended receptor, in the intended or another tissue","Diphenhydramine drowsiness: on-target, wrong tissue (histamine receptors in the brain)","Off-target example: terfenadine inhibiting cardiac potassium channels, the S-enantiomer of thalidomide, or propranolol blocking beta-2 receptors in the airway"],"quote":"but it causes drowsiness because it's hitting the histamine receptors in the brain, so that's an on target adverse effect in the wrong tissue.","cite":"Toxic Responses Students Fall 2026 WCAG21A.pdf slides ‘On-target and off-target adverse drug effects’, ‘On-Target Examples’, ‘Off-Target Examples’; transcript 10/13"},{"id":"SA3-14","lecture":"TBL3","form":"key","q":"Acetaminophen overdose (OD): name the antidote and its mechanism of action. At what time after OD does the antidote lose effectiveness? Should you still give it past that time point?","model":"The antidote is N-acetylcysteine (NAC), which replenishes glutathione by supplying ingredients the body uses to make more of it. It loses effectiveness about 8 hours after the overdose, and yes, it should still be given past that time point.","points":["Antidote: N-acetylcysteine (NAC)","Mechanism: replenishes glutathione","Loses effectiveness about 8 hours after the overdose","Still give it after that time point: yes"],"quote":"And it's giving ingredients to the system to create more glutathione.","cite":"PoisoningTreatmentTable2026KEY.pdf, row ‘Acetaminophen’; Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Toxicokinetic-Based Treatment Acetaminophen Example’; Marraffa+AJHSP+2012+Antidotes.pdf; transcript 10/19","note":"Her two special-consideration questions are verbatim from the key. Marraffa: even after fulminant hepatic failure, when all the acetaminophen has been metabolized, intravenous NAC is still beneficial."}],"miss":{"shift":["Shift","Did the curve move left or right of the point of reference (the agonist alone)?"],"baseline":["Baseline","Where does the curve start? Only an agonist raises it; only an inverse agonist takes it down to 0."],"emax":["Emax","Does the maximum change? Only an irreversible antagonist, or an allosteric antagonist that affects efficacy, lowers it."],"symmetry":["Symmetry","Are the steps equal for equal doses (competitive, no limit) or shrinking and then stopping (allosteric, saturable)?"],"direction":["Helping or hurting","Is the second drug helping the agonist (left) or making life more difficult (right)?"],"potency":["Potency","Which curve reaches the response at the lowest dose? The one furthest left (smallest ED50)."],"efficacy":["Efficacy","Which curve reaches the highest maximum? Potency says nothing about how high it goes."],"affinity":["Affinity","The smaller the Kd, the greater the affinity; check the units (nM < µM < mM)."],"class":["Drug class","The reading was right; match it to the class: which drug on the list produces that curve?"],"steps":["Steps","Signal → receptor → transducer (G protein) → effector → second messenger; GDP off, GTP on."],"ti":["Therapeutic index","TI = LD50 / ED50: find both 50% points on the quantal curves and divide; the larger, the safer."],"read":["Read the figure","Axes, legend and point of reference first: which curve is the agonist alone?"]},"miss2":{"direction":["Helping or hurting","Which way does the response go after the drug, and does the second drug help the first (more of the same response) or block it?"],"class":["Which drug","The reading was right; now name it: which receptor does the drug act on (agonist, antagonist, indirect), and which drug on the list does that?"],"read":["Read the tracing","Tissue, response and arrows first: what is measured, what was given when, and what was the response before the drug?"],"affinity":["Which receptor","Which receptor does the drug act on in this tissue (M3, β1, β2, α1, Nm), and what does that receptor do here?"]}};
/* app.js vGraphs INTRO, with "his" written as "the professor's"; the Exam 2
   tracing wording of app.js (graphFeedback, vGraphs): noun and group name. */
const EXAMS = {1: {intro: "Dose–response curves from the professor's PollEV polls, Jeopardy, the 9/30 review and Part 3: read the shift, the baseline and the maximum."},
  2: {intro: "Tissue tracings from the professor's Exam 2 polls and review: read which tissue and response are measured, which receptor the drug acts on, and whether the response is helped or blocked.",
      noun: 'tracing', other: 'Tissue tracings', miss: IP.miss2}};
/* app.js vSa's subtitle, with "Her exam" written as "The professor's exam" */
const SA_ABOUT = "The professor's exam has two short-answer questions graded with partial credit.";
const qpre = id => 'sag-' + id;

function fixtureFiles(own, opts){
  opts = opts || {};
  const copy = x => JSON.parse(JSON.stringify(x));
  const qs = copy(IP.qs).map(q => { const c = Object.assign(q, {id: qpre(q.id), prof: own.prof, skill: own.skill}); delete c.fg; return c; });
  const graphs = copy(IP.graphs), sa = copy(IP.sa).map(p => Object.assign(p, {id: qpre(p.id)}));
  if(opts.mutate) opts.mutate({qs, graphs, sa});
  const topics = IP.topics.filter(t => !own.topics.includes(t.id)).map(t => Object.assign({}, t, {prof: own.prof}));
  const list = (name, rows, has) => has ? `${name}.push(...${JSON.stringify(rows)});` : `const ${name} = ${JSON.stringify(rows)};`;
  const obj = (name, value, has) => has ? `Object.assign(${name}, ${JSON.stringify(value)});` : `const ${name} = ${JSON.stringify(value)};`;
  let data = '/* Intro-Pharmacology\'s short answers, figures and miss tables (929cd62), added by the short-answer-graphs test */\n' +
    list('SHORT_ANSWERS', sa, own.SA) + '\n';
  if(!opts.noGraphs) data += list('GRAPHS', graphs, own.GR) + '\n' + obj('GRAPH_MISS', IP.miss, own.GM) + '\n' + obj('GRAPH_EXAMS', EXAMS, own.GE) + '\n';
  if(opts.empty) data += 'SHORT_ANSWERS.length = 0;\n' + (own.GR || !opts.noGraphs ? 'GRAPHS.length = 0;\n' : '');
  const files = {'sag_test_data.js': data};
  if(!opts.noGraphs) files['q90_sag_fixture.js'] = '/* 10 of Intro-Pharmacology\'s figure questions (929cd62), added by the short-answer-graphs test */\n' +
    `TOPICS.push(...${JSON.stringify(topics)});\nQUESTIONS.push(...${JSON.stringify(qs)});\n`;
  return files;
}
const courseLine = "COURSE.files = (COURSE.files || ['atlas.js', 'diagrams.js', 'q1_topics.js']).filter(f => f !== 'sag_test_data.js').concat(['sag_test_data.js']);" +
  L.featureOn(__dirname, {saAbout: SA_ABOUT});
const addImages = src => { const p = path.join(src, 'images.json'); fs.writeFileSync(p, JSON.stringify(Object.assign(JSON.parse(fs.readFileSync(p, 'utf8')), IP.images))); };
const build = (label, own, opts) => L.scratchBuild(label, {files: fixtureFiles(own, opts), courseLine, edit: addImages});

(async () => {
  console.log('\n=== the course\'s own short answers and figures ===');
  L.PAGE.need(NAME);
  const X = L.engine('({SA: typeof SHORT_ANSWERS === "undefined" ? null : SHORT_ANSWERS, GR: typeof GRAPHS === "undefined" ? null : GRAPHS,' +
    ' GM: typeof GRAPH_MISS === "undefined" ? null : GRAPH_MISS, GE: typeof GRAPH_EXAMS === "undefined" ? null : GRAPH_EXAMS, QUESTIONS, TOPICS, COURSE, FX})');
  const A = X.FX && X.FX.api('short-answer-graphs');
  if(!check(!!A, 'the page carries short-answer-graphs, working', JSON.stringify((X.FX && X.FX.errors) || 'no feature modules in the page'))) L.finish(NAME);
  if(A.GR.length){
    const empty = A.GR.filter(g => !A.graphQs(g).length).map(g => g.key);
    check(!empty.length, `every figure has questions (${A.GR.length} figures, ${A.GR.reduce((n, g) => n + A.graphQs(g).length, 0)} questions)`, empty.join(', '));
    const unnamed = [];
    A.GR.forEach(g => A.graphQs(g).forEach(q => (q.options || []).forEach(o => { if(!o.correct && o.miss && !A.missOf(g, o.miss)[1]) unnamed.push(q.id + ':' + o.miss); })));
    check(!unnamed.length, 'every miss tag on a figure question names a reading question', unnamed.slice(0, 6).join(', '));
    const tr = A.GR.find(g => (X.GE || {})[g.exam || 1] && X.GE[g.exam || 1].noun === 'tracing');
    const tq = tr && A.graphQs(tr).find(q => q.options && q.options.some(o => !o.correct && o.miss));
    if(tq){
      const h = A.graphFeedback(tq, {ok: false, picked: tq.options.findIndex(o => !o.correct && o.miss)});
      const skip = (h.match(/<div class="gskip">[\s\S]*?<\/div>/) || [''])[0];
      check(skip && !/curve/i.test(skip) && /tracing/.test(h), `a tracing's feedback uses tracing wording, not curve wording (${tq.id})`, h.slice(0, 200));
    } else L.skip('tracing wording', 'the course has no figure with tracing wording and a miss tag');
  } else L.skip('the course\'s figures', 'the course declares no GRAPHS');
  if(A.SA_LIST.length){
    const bad = A.SA_LIST.filter(p => !Array.isArray(p.points) || !p.points.length).map(p => p.id);
    check(!bad.length, `every short-answer prompt has key points (${A.SA_LIST.length} prompts)`, bad.join(', '));
  } else L.skip('the course\'s short answers', 'the course declares no SHORT_ANSWERS');

  const own = {SA: !!X.SA, GR: !!X.GR, GM: !!X.GM, GE: !!X.GE, topics: X.TOPICS.map(t => t.id), prof: X.COURSE.professors[0],
               skill: (X.COURSE.skills.find(s => s.id === 'read') || X.COURSE.skills[0]).id};

  console.log('\n=== the build step stops on bad data ===');
  const refusals = [
    ['an image that is not in images.json', {mutate: d => { d.graphs[0].alts = ['sag-no-such-image']; }}, /"sag-no-such-image" is not in images\.json/],
    ['an image in two figures', {mutate: d => { d.graphs[1].alts = [d.graphs[0].key]; }}, /is also in the figure/],
    ['a miss tag in no table', {mutate: d => { d.qs[0].options.find(o => !o.correct).miss = 'sag-nowhere'; }}, /"sag-nowhere" is in neither GRAPH_MISS/],
    ['a figure with no question', {mutate: d => { d.qs.forEach(q => { if(q.img === d.graphs[0].key) delete q.img; }); }}, /no question has this figure/],
    ['a prompt with no key points', {mutate: d => { d.sa[0].points = []; }}, /points is not a list of one or more key points/],
    ['a prompt id used twice', {mutate: d => { d.sa[1].id = d.sa[0].id; }}, /is used twice/],
    ['a course with neither list', {empty: true}, /neither SHORT_ANSWERS nor GRAPHS has rows/]];
  for(const [label, opts, want] of refusals){
    const r = build('sag-refuse', own, opts);
    check(r.code !== 0 && want.test(r.out), `${label} stops the build and says so`, r.out.split('\n').slice(-2).join(' '));
    r.rm();
  }

  console.log('\n=== on a scratch copy with Intro-Pharmacology\'s rows (Chromium) ===');
  const s = build('sag', own);
  if(s.code !== 0) L.notRun(NAME, 'the scratch copy with the test rows does not build: ' + s.out.split('\n').pop());
  const s2 = own.GR ? null : build('sag-saonly', own, {noGraphs: true});
  const {browser} = await L.launch(NAME);
  try {
    const {ctx, page, errors} = await L.openPage(browser, s.page, {viewport: {width: 1100, height: 1300}});
    const ev = (f, a) => page.evaluate(f, a);
    const nav = await ev(() => [...document.querySelectorAll('#nav button')].map(b => b.dataset.v));
    check(nav.indexOf('sa') >= 0 && nav.indexOf('graphs') === nav.indexOf('sa') + 1 && nav.indexOf('diagrams') === nav.indexOf('graphs') + 1,
          'the Short answer and Graphs tabs sit before Diagrams', nav.join(','));

    // graphs: one card per registered figure, in a fold per exam (browser_test.js lines 114-117)
    await page.click('#nav button[data-v="graphs"]');
    const gc = await ev(() => ({cards: document.querySelectorAll('#v-graphs .gcard').length, reg: GRAPHS.length,
      folds: [...document.querySelectorAll('#v-graphs details.gexam')].map(d => d.dataset.ex + (d.open ? ':open' : ':shut')),
      tissue: [...document.querySelectorAll('#v-graphs details.gexam[data-ex="2"] h3')].map(h => h.textContent),
      intro: !!document.querySelector('#v-graphs details.gexam[data-ex="2"] p.sub'),
      thumbs: document.querySelectorAll('#v-graphs .gcard .gthumb img').length}));
    check(gc.cards === gc.reg && gc.thumbs === gc.reg, `one card per figure, each with its image (${gc.cards} cards, ${gc.reg} figures)`, gc);
    check(gc.folds.includes('1:open') && gc.folds.includes('2:shut') && gc.tissue.includes('Tissue tracings') && gc.intro,
          'a fold per exam, the active exam open; the Exam 2 fold names its group Tissue tracings and has its intro line', gc);
    const card0 = await ev(() => document.querySelector('#v-graphs .gcard[data-gkey="rev-pindolol"] .meta').textContent);
    const n0 = await ev(() => FX.api('short-answer-graphs').graphQs(GRAPHS.find(g => g.key === 'rev-pindolol')).length);
    check(card0.startsWith(`${n0} questions · ${n0} unseen · 0 right · 0 wrong`), `the card counts the figure's questions, all unseen (${n0})`, card0);

    // Drill this figure: a question on that figure with its image (browser_test.js lines 118-120)
    await page.click('#v-graphs .gcard[data-gkey="rev-pindolol"] [data-g]:not([data-wrong])');
    const d1 = await ev(() => ({img: !!document.querySelector('#v-quiz img.qimg'), alt: (document.querySelector('#v-quiz img.qimg') || {}).alt,
      want: Q.current && Q.current.imgAlt, graph: Q.graph, n: Q.sweep.length, view: VIEW}));
    check(d1.view === 'quiz' && d1.img && d1.graph === 'rev-pindolol' && d1.n === n0, `Drill this figure opens a pass of its ${n0} questions, with its figure`, d1);
    check(d1.alt === d1.want, 'the figure carries the question\'s own description as its alt text', d1.alt);

    // a wrong pick on a tagged option: the reading question skipped, and the reading (browser_test.js lines 121-122)
    const wrong = await ev(() => Q.current.options.findIndex(o => !o.correct && o.miss));
    await page.click(`#v-quiz .opt[data-o="${wrong}"]`);
    const w = await ev(i => { const A = FX.api('short-answer-graphs'), g = A.graphOf(Q.current.img), tag = Q.current.options[i].miss;
      const rd = document.querySelector('#v-quiz details.gread');
      return {skip: (document.querySelector('#v-quiz .gskip') || {}).textContent || '', label: A.missOf(g, tag)[0], q: A.missOf(g, tag)[1],
              read: rd ? rd.querySelectorAll('li').length : 0, want: g.read.length, open: !!(rd && rd.open),
              sum: rd ? rd.querySelector('summary').textContent : '', order: !!document.querySelector('#v-quiz .why .verdict + .gskip')}; }, wrong);
    check(w.skip.includes(w.label) && w.skip.includes(w.q) && w.order, 'a wrong pick names the reading question skipped, under the verdict', w);
    check(w.read === w.want && w.open && w.sum === "Read this figure the professor's way", 'the figure\'s reading is open, every line of it', w);

    // the rest answered right; the pass's end
    for(let k = 1; k < n0; k++){
      await page.click('#v-quiz #btnNext');
      const ok = await ev(() => { const q = Q.current; if(!q) return null; if(q.multi){ return -1; } return q.options.findIndex(o => o.correct); });
      if(ok === null) break;
      if(ok === -1){ await ev(() => { Q.current.options.forEach((o, i) => { if(o.correct) toggleOption(i); }); submitMulti(); }); }
      else await page.click(`#v-quiz .opt[data-o="${ok}"]`);
      if(k === 1) check(await ev(() => !document.querySelector('#v-quiz .gskip') && document.querySelector('#v-quiz details.gread') && !document.querySelector('#v-quiz details.gread').open),
                        'a right answer shows the reading folded and names nothing skipped');
    }
    await page.click('#v-quiz #btnNext');
    const done = await ev(() => ({card: !!document.querySelector('#v-quiz .gdone'), text: (document.querySelector('#v-quiz .gdone') || {}).textContent || '',
      li: [...document.querySelectorAll('#v-quiz .gdone li')].map(x => x.textContent)}));
    check(done.card && done.text.includes(`${n0 - 1} of ${n0} correct.`), `the end of the pass counts the right answers (${n0 - 1} of ${n0})`, done.text.slice(0, 160));
    check(done.li.length === 1 && done.li[0].startsWith(w.label + ' (1×)'), 'it lists the reading question skipped, with how often', done.li);

    await page.click('#v-quiz #gback');
    const card1 = await ev(() => { const c = document.querySelector('#v-graphs .gcard[data-gkey="rev-pindolol"]');
      return {meta: c.querySelector('.meta').textContent, skip: (c.querySelector('.gyouskip') || {}).textContent || '', redo: !!c.querySelector('[data-wrong]'), view: VIEW}; });
    check(card1.view === 'graphs' && card1.meta.startsWith(`${n0} questions · 0 unseen · ${n0 - 1} right · 1 wrong`) && card1.skip === `You skip: ${w.label} ×1` && card1.redo,
          'All figures goes back; the card shows the wrong answer, the reading skipped and Redo wrong', card1);
    await page.click('#v-graphs .gcard[data-gkey="rev-pindolol"] [data-wrong]');
    const redo = await ev(() => ({n: Q.sweep.length, label: Q.label}));
    check(redo.n === 1 && / · wrong$/.test(redo.label), 'Redo wrong asks only the question answered wrong', redo);

    // a tracing (Exam 2): its own miss wording and the tracing reading (browser_test.js C8, line 325)
    await ev(() => FX.api('short-answer-graphs').startGraph('pe2-gi-tracing'));
    const tw = await ev(() => Q.current.options.findIndex(o => !o.correct && o.miss));
    await page.click(`#v-quiz .opt[data-o="${tw}"]`);
    const t2 = await ev(() => ({skip: (document.querySelector('#v-quiz .gskip') || {}).textContent || '', sum: (document.querySelector('#v-quiz details.gread summary') || {}).textContent}));
    const tag2 = await ev(i => Q.current.options[i].miss, tw);
    const want2 = (IP.miss2[tag2] || IP.miss[tag2])[0];
    check(t2.skip.includes(want2) && !/curve/i.test(t2.skip) && t2.sum === "Read this tracing the professor's way",
          `a tracing names its skipped question in tracing wording, not curve wording (tag ${tag2})`, t2);

    // the counts survive a reload (after the core's save, 150 ms after the last answer)
    await page.waitForTimeout(400);
    await page.reload();
    await page.waitForFunction(() => document.querySelectorAll('#nav button').length > 3, null, {timeout: 15000});
    await page.click('#nav button[data-v="graphs"]');
    const card2 = await ev(() => document.querySelector('#v-graphs .gcard[data-gkey="rev-pindolol"] .meta').textContent);
    check(card2.startsWith(`${n0} questions · 0 unseen · ${n0 - 1} right · 1 wrong`), 'the counts on the card are kept through a reload', card2);

    // Short answer
    await page.click('#nav button[data-v="sa"]');
    const sa0 = await ev(() => ({head: document.querySelector('#v-sa .sahead b').textContent, sub: document.querySelector('#v-sa p.sub').textContent,
      meta: document.querySelector('#v-sa .sacard .meta').textContent, stem: document.querySelector('#v-sa .stem').textContent, id: SHORT_ANSWERS[0].id,
      q: SHORT_ANSWERS[0].q, n: SHORT_ANSWERS.length, prev: document.querySelector('#saprev').disabled, model: !!document.querySelector('#v-sa .teach')}));
    check(sa0.head === `Prompt 1 of ${sa0.n}` && sa0.stem === sa0.q && sa0.prev && !sa0.model, `the page shows the first of ${sa0.n} prompts, the model answer hidden`, sa0);
    check(sa0.sub.startsWith(SA_ABOUT) && sa0.meta.endsWith(" · the professor's wording"), 'the course\'s line on its short answers, and the prompt\'s form, are shown', sa0);
    await page.fill('#satext', 'Relatively less warfarin.');
    const typed = await ev(() => (DB.sa || {})[SHORT_ANSWERS[0].id]);
    check(typed && typed.text === 'Relatively less warfarin.', 'the draft is kept in the progress as it is typed', typed);
    await page.click('#sacheck');
    const shown = await ev(() => ({model: (document.querySelector('#v-sa .teach') || {}).textContent || '', pts: document.querySelectorAll('#v-sa [data-sapt]').length,
      want: SHORT_ANSWERS[0].points.length, m: SHORT_ANSWERS[0].model, checked: (DB.sa[SHORT_ANSWERS[0].id] || {}).checked,
      head: document.querySelector('#v-sa .sahead .meta').textContent, cite: [...document.querySelectorAll('#v-sa .cite')].map(c => c.textContent).join(' | '),
      src: SHORT_ANSWERS[0].cite || '', quote: SHORT_ANSWERS[0].quote || '',
      btn: document.querySelector('#sacheck').textContent}));
    check(shown.model.includes(shown.m) && shown.pts === shown.want && shown.checked === true && shown.head === '1 checked' && shown.btn === 'Hide the model answer',
          'Check my answer shows the model answer and each key point to tick, and counts the prompt checked', shown);
    check(shown.cite.includes(shown.src) && shown.cite.includes(shown.quote.slice(0, 40)), 'the quote and the source are shown with it', shown.cite.slice(0, 120));
    await page.click('#v-sa [data-sapt="0"]'); await page.click('#v-sa [data-sapt="2"]');
    const sc = await ev(() => ({score: document.querySelector('#sascore').textContent, ticks: DB.sa[SHORT_ANSWERS[0].id].ticks}));
    check(sc.score === `2 of ${shown.want} key points` && JSON.stringify(sc.ticks) === '[0,2]', 'ticking key points counts them and keeps them', sc);
    await page.waitForTimeout(400);
    await page.reload();
    await page.waitForFunction(() => document.querySelectorAll('#nav button').length > 3, null, {timeout: 15000});
    const back = await ev(() => ({view: VIEW, text: (document.querySelector('#satext') || {}).value}));
    if(back.view !== 'sa') await page.click('#nav button[data-v="sa"]');
    await page.click('#sacheck');
    const kept = await ev(() => ({text: document.querySelector('#satext').value, on: [...document.querySelectorAll('#v-sa [data-sapt]')].filter(x => x.checked).map(x => +x.dataset.sapt)}));
    check(back.view === 'sa' && kept.text === 'Relatively less warfarin.' && JSON.stringify(kept.on) === '[0,2]', 'a reload comes back to the page with the draft and the ticks', {back, kept});

    await page.click('#sanext');
    const p2 = await ev(() => ({head: document.querySelector('#v-sa .sahead b').textContent, model: !!document.querySelector('#v-sa .teach'), prev: document.querySelector('#saprev').disabled}));
    check(p2.head === `Prompt 2 of ${sa0.n}` && !p2.model && !p2.prev, 'Next shows the next prompt with its model answer hidden', p2);
    const forms = [];
    for(let k = 2; k < sa0.n; k++){ await page.click('#sanext'); forms.push(await ev(() => document.querySelector('#v-sa .sacard .meta').textContent)); }
    const lastNext = await ev(() => document.querySelector('#sanext').disabled);
    check(forms.some(f => f.endsWith(" · the professor's key")) && forms.some(f => !/the professor's/.test(f)) && lastNext,
          'a key prompt says so, an objective prompt carries no form, and Next stops at the last', forms);
    await page.click('#saprev');
    check(await ev(n => document.querySelector('#v-sa .sahead b').textContent === `Prompt ${n - 1} of ${n}`, sa0.n), 'Previous goes back one prompt');
    await page.click('#sashuf');
    const sh = await ev(() => { const A = FX.api('short-answer-graphs').state().SA; return {i: A.i, order: A.order.slice().sort((a, b) => a - b).join(','), n: SHORT_ANSWERS.length}; });
    check(sh.i === 0 && sh.order === [...Array(sh.n).keys()].join(','), 'Shuffle starts again at prompt 1, every prompt kept', sh);
    await ev(() => { const A = FX.api('short-answer-graphs').state().SA; A.order = A.order.map((x, k) => k); A.i = 0; show('sa'); });
    await page.click('#saclear');
    const cl = await ev(() => ({text: document.querySelector('#satext').value, st: DB.sa[SHORT_ANSWERS[0].id], head: document.querySelector('#v-sa .sahead .meta').textContent}));
    check(cl.text === '' && cl.st.text === '' && !cl.st.ticks.length && cl.st.checked === false && cl.head === '0 checked', 'Clear empties the draft and the ticks', cl);

    check(!errors.length, 'no page errors', errors.slice(0, 3));
    check(await ev(() => !FX.errors.length), 'the module raised no error', await ev(() => FX.errors.slice(0, 3)));
    await ctx.close();

    if(s2 && s2.code === 0){
      const o = await L.openPage(browser, s2.page);
      const tabs = await o.page.evaluate(() => [...document.querySelectorAll('#nav button')].map(b => b.dataset.v));
      check(tabs.includes('sa') && !tabs.includes('graphs') && !o.errors.length, 'with short answers only, there is no Graphs tab', tabs.join(','));
      await o.ctx.close();
    } else if(s2) check(false, 'the copy with short answers only builds', s2.out.split('\n').pop());
    else L.skip('no Graphs tab without figures', 'the course declares GRAPHS itself');
  } finally {
    await browser.close();
    s.rm(); if(s2) s2.rm();
  }
  L.finish(NAME);
})().catch(e => { console.log('FAIL: ' + NAME + ': ' + String(e && e.stack || e).split('\n').slice(0, 3).join(' ')); process.exit(1); });
